# This program does basic math.

import math


def main():
    print("6 + 6={}".format(6 + 6))
    print("53 - 28={}".format(53 - 28))
    print("6 * 6={}".format(6 * 6))
    print("9 / 3={}".format(9 / 3))
    print("3 ^ 5={}".format(3 ^ 5))
    print("√8={}".format(math.sqrt(8)))


if __name__ == "__main__":
    main()
